import {readFileSync,writeFileSync,mkdirSync,existsSync} from 'node:fs';
import {dirname,resolve} from 'node:path';
const root=resolve(import.meta.dirname,'..');
const catalog=JSON.parse(readFileSync(resolve(root,'src/catalog.json'),'utf8'));
const products=catalog.products;
const base=process.env.BASE_PATH||'/aerlor/';
if(!/^\/[a-zA-Z0-9/_-]*\/$/.test(base)&&base!=='/')throw new Error('Invalid BASE_PATH');
const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=p=>base+p.replace(/^\//,'');
const img=n=>`/images/${n}`;
const arrow='<span aria-hidden="true">↗</span>';
const link=(text,path,kind='button-dark')=>`<a class="button ${kind}" href="${url(path)}">${text}${arrow}</a>`;
const small=(text,path)=>`<a class="text-link" href="${url(path)}">${text}${arrow}</a>`;
const eye=text=>`<p class="eyebrow">${text}</p>`;
const note='<p class="collection-note">Collection in development. Visuals show design studies. Final specifications, market approvals, pricing and availability are confirmed before an order is accepted.</p>';
const familyData={hairdryers:{name:'Hairdryers',title:'A better start.<br><em>A beautiful finish.</em>',intro:'The appliance a guest reaches for without thinking can become a detail they are glad you thought about.',body:'Two design directions. One ambition: make the everyday haircare ritual feel as considered as the room around it.',image:'dryer-champagne.svg'},mirrors:{name:'Illuminated mirrors',title:'The right light.<br><em>Their best moment.</em>',intro:'A guest should not have to choose between a beautiful room and a useful place to get ready.',body:'Our freestanding makeup-mirror concepts bring the dressing space into focus, from a practical everyday expression to a signature suite statement.',image:'mirror-premium.svg'},curlers:{name:'Curling tools',title:'Before the evening.<br><em>After the thought.</em>',intro:'A celebration, a dinner reservation, a reason to feel like yourself. Build a service that is ready for the moment.',body:'Lite and Premium styling-tool directions for carefully managed, on-request amenities. A more personal service starts with a clear safety and lending plan.',image:'curler-premium.svg'}};
const sources=[
{id:'hair-routine',title:'Packing hair products',publisher:'r/HerOneBag',url:'https://www.reddit.com/r/HerOneBag/comments/1h1vp94/packing_hair_products/',type:'First-person public discussion',note:'Contributors describe choosing between packing familiar tools and relying on hotel dryers. Other contributors are happy to use the hotel dryer or simplify their routine. These are self-selected anecdotes, not a representative survey.'},
{id:'styling-bulk',title:'What hair styling tools do you take traveling?',publisher:'r/HerOneBag',url:'https://www.reddit.com/r/HerOneBag/comments/1iz75yy/what_hair_styling_tools_do_you_take_traveling/',type:'First-person public discussion',note:'The original poster describes a familiar styling tool as too bulky for travel. Replies differ on whether and what to pack.'},
{id:'mirror-position',title:'Travel mirror recommendations please',publisher:'Mumsnet, 5 May 2024',url:'https://www.mumsnet.com/talk/style_and_beauty/5068902-travel-mirror-recommendations-please',type:'First-person public discussion',note:'A traveller asks about a mirror for use while the bathroom is occupied, then explains that room mirrors can be poorly lit or difficult to approach.'},
{id:'hyatt-drybar',title:'Hyatt Centric announces Drybar collaboration',publisher:'Hyatt Newsroom, 10 May 2016',url:'https://newsroom.hyatt.com/051016Hyatt-Centric-Steps-Up-Its-Style-With-First-Ever-Drybar-Collaboration',type:'Historical operator announcement',note:'Hyatt announced an in-room premium dryer rollout in 2016. This is category precedent, not evidence about current availability at every hotel or AERLOR performance.'},
{id:'lighted-mirror',title:'Services & amenities',publisher:'Four Seasons Resort Oahu',url:'https://www.fourseasons.com/oahu/accommodations/shared-services/',type:'Operator amenity listing',note:'The operator lists a lighted makeup and shaving mirror. It is not an AERLOR customer or endorsement.'},
{id:'borrowing',title:'Hyatt Has It',publisher:'Hyatt',url:'https://www.hyatt.com/info/hyatt-has-it-program',type:'Operator service description',note:'Hyatt describes essentials guests can buy or borrow. This supports an on-request service model, not any AERLOR partnership.'}
];
writeFileSync(resolve(root,'src/evidence.json'),JSON.stringify({checkedAt:'2026-11-04',scope:'Qualitative category evidence; not AERLOR customer testimonials or proof of revenue impact.',sources},null,2));
const header=()=>`<header class="site-header commerce-header" id="header"><nav class="nav-left" aria-label="Main navigation"><details class="nav-disclosure"><summary>Collection <span aria-hidden="true">⌄</span></summary><div class="nav-panel"><a href="${url('collection/')}">Discover everything</a><a href="${url('collection/hairdryers/')}">Hairdryers</a><a href="${url('collection/mirrors/')}">Makeup mirrors</a><a href="${url('collection/curlers/')}">Curling tools</a></div></details><a href="${url('hospitality/')}">For hotels</a><a href="${url('pricing/')}">Pricing</a></nav><a class="wordmark" href="${base}" aria-label="AERLOR home">AERLOR</a><nav class="nav-right" aria-label="Company navigation"><a href="${url('resources/')}">Resources</a><a href="${url('contact/')}">Contact</a><a class="bag-link" href="${url('cart/')}" aria-label="Your project bag, 0 items"><svg width="19" height="21" viewBox="0 0 19 21" fill="none" aria-hidden="true"><path d="M2 6.5h15l1 13H1l1-13ZM6 7V4a3.5 3.5 0 0 1 7 0v3" stroke="currentColor"/></svg><span class="bag-count" data-cart-count>0</span></a></nav><button class="menu-toggle" aria-controls="mobile-menu" aria-expanded="false" aria-label="Open menu"><span></span><span></span></button></header><nav class="mobile-menu" id="mobile-menu" aria-label="Mobile navigation" hidden><a href="${url('collection/')}">The collection</a><a href="${url('collection/hairdryers/')}">Hairdryers</a><a href="${url('collection/mirrors/')}">Makeup mirrors</a><a href="${url('collection/curlers/')}">Curling tools</a><a href="${url('hospitality/')}">For hotels</a><a href="${url('pricing/')}">Pricing & wholesale</a><a href="${url('resources/')}">Resource library</a><a href="${url('about/')}">Our philosophy</a><a href="${url('contact/')}">Contact AERLOR</a><a href="${url('cart/')}">Your project bag <span data-cart-count>0</span></a></nav>`;
const footer=()=>`<footer class="footer site-footer"><div class="footer-intro"><div>${eye('CONSIDERED ESSENTIALS. EXCEPTIONAL STAYS.')}<p class="footer-statement">Make room<br>for <em>better mornings.</em></p></div><div class="footer-links"><div><h3>Collection</h3><a href="${url('collection/hairdryers/')}">Hairdryers</a><a href="${url('collection/mirrors/')}">Makeup mirrors</a><a href="${url('collection/curlers/')}">Curling tools</a><a href="${url('compare/')}">Compare the collection</a></div><div><h3>Hospitality</h3><a href="${url('hospitality/')}">The guest experience</a><a href="${url('hospitality/wholesale/')}">Wholesale & bulk</a><a href="${url('hospitality/groups/')}">Hotel groups</a><a href="${url('hospitality/designers/')}">Designers & specifiers</a><a href="${url('pricing/')}">Pricing process</a></div><div><h3>AERLOR</h3><a href="${url('about/')}">Our perspective</a><a href="${url('journal/the-getting-ready-gap/')}">Guest perspectives</a><a href="${url('resources/')}">Downloads & documents</a><a href="${url('contact/')}">Contact the team</a><a href="${url('support/')}">Support</a></div></div></div><a href="${base}" class="footer-logo" aria-label="AERLOR home">AERLOR</a><div class="footer-bottom"><span>© 2026 AERLOR.</span><span>Collection development · not yet available to purchase</span><div><a href="${url('privacy/')}">Privacy</a><a href="${url('terms/')}">Terms</a><a href="${url('accessibility/')}">Accessibility</a></div></div></footer><div class="toast" id="cart-notice" role="status" aria-live="polite" hidden></div>`;
const head=(title,desc)=>`<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f3f0e9"><meta name="robots" content="noindex,nofollow"><meta name="description" content="${e(desc)}"><meta property="og:title" content="${e(title)} | AERLOR"><meta property="og:description" content="${e(desc)}"><meta property="og:type" content="website"><title>${e(title)} | AERLOR</title><link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=DM+Sans:wght@400;450;500;550;600;650&display=swap" rel="stylesheet"><link rel="stylesheet" href="/src/style.css"><link rel="stylesheet" href="/src/storefront.css">`;
const paths=[];
function page(path,title,desc,content,attrs=''){const file=resolve(root,path,'index.html');mkdirSync(dirname(file),{recursive:true});writeFileSync(file,`<!doctype html><html lang="en"><head>${head(title,desc)}</head><body data-page="${e(path)}" ${attrs}><a class="skip-link" href="#main">Skip to content</a>${header()}<main id="main">${content}</main>${footer()}<noscript><p class="noscript-note">You can read every product and download the collection documents without JavaScript. The project bag, calculators and checkout require JavaScript.</p></noscript><script type="module" src="/src/storefront.ts"></script></body></html>`);paths.push(path+'/index.html');}
const breadcrumb=(label,parent='Collection',parentPath='collection/')=>`<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="${base}">Home</a><span aria-hidden="true">/</span><a href="${url(parentPath)}">${parent}</a><span aria-hidden="true">/</span><span aria-current="page">${e(label)}</span></nav>`;
const hero=(kicker,title,desc,art,cls='')=>`<section class="page-hero ${cls}"><div class="page-hero-copy">${eye(kicker)}<h1>${title}</h1><p class="lead">${desc}</p></div>${art?`<div class="page-hero-art"><img src="${img(art)}" alt="Original AERLOR collection design study" width="800" height="900" fetchpriority="high"><span class="art-label">DESIGN STUDY / AERLOR</span></div>`:''}</section>`;
function card(p){return `<article class="catalog-card" data-catalog-card data-family="${p.family}" data-tier="${p.tier}"><a class="catalog-art ${p.tier==='Premium'?'premium-art':'lite-art'}" href="${url('products/'+p.slug+'/')}"><span>${e(p.family.toUpperCase())} / ${e(p.tier.toUpperCase())}</span><img src="${img(p.image)}" alt="${e(p.name)} ${e(p.finish)} design study" width="800" height="900" loading="lazy"><small>DESIGN STUDY</small></a><div class="catalog-title"><h3><a href="${url('products/'+p.slug+'/')}">${e(p.name)}</a></h3><span data-price="${p.id}">Quote-led</span></div><p>${e(p.tagline)}</p><div class="catalog-actions">${small('Discover '+p.tier,'products/'+p.slug+'/')}<button class="icon-add" data-add="${p.id}" aria-label="Add ${e(p.name)} to your project">+</button></div></article>`;}
const grid=list=>`<div class="catalog-grid">${list.map(card).join('')}</div>`;
const categories=()=>`<section class="category-stories section-pad">${eye('A COMPLETE GETTING-READY RITUAL')}<div class="section-heading"><h2>Dry. Reflect.<br><em>Make an entrance.</em></h2><p>Three moments. Two expressions.<br>A coherent collection for the way your guests get ready.</p></div><div class="category-grid">${Object.entries(familyData).map(([key,f],i)=>`<a class="category-card category-${key}" href="${url('collection/'+key+'/')}"><div class="category-image"><img src="${img(f.image)}" width="700" height="800" alt="${e(f.name)} concept" loading="lazy"><span>0${i+1}</span></div><div><h3>${e(f.name)}</h3>${arrow}</div><p>${key==='hairdryers'?'The first step in a better morning.':key==='mirrors'?'A more thoughtful place to get ready.':'A little confidence before stepping out.'}</p></a>`).join('')}</div></section>`;
const cta=(title='A thoughtful room starts<br>with a thoughtful <em>conversation.</em>',text='Tell us about the rooms, the guests and the experience you want to create.')=>`<section class="editorial-cta"><div>${eye('LET’S BUILD YOUR ROOM STANDARD')}<h2>${title}</h2><p>${text}</p></div>${link('Plan your property','hospitality/wholesale/','button-light')}</section>`;
const band=(title,body)=>`<aside class="quiet-note"><strong>${title}</strong><p>${body}</p></aside>`;
const voices=()=>`<div class="voice-grid"><article>${eye('THE FAMILIAR ROUTINE')}<h3>“It does feel tough to me<br>rely on the hotel dryer.”</h3><p>A contributor who uses a familiar styling tool at home describes the compromise involved in relying on hotel equipment.</p><a href="${sources[0].url}" target="_blank" rel="noopener noreferrer">Read the public discussion <span aria-hidden="true">↗</span></a></article><article>${eye('THE SUITCASE TRADE-OFF')}<h3>The tool they love.<br>The space it takes.</h3><p>In another travel discussion, the original poster wants a styling solution that does not take up the space of their usual tool.</p><a href="${sources[1].url}" target="_blank" rel="noopener noreferrer">Read the public discussion <span aria-hidden="true">↗</span></a></article><article>${eye('THE MIRROR THAT WORKS')}<h3>A mirror is only useful<br>in the right place.</h3><p>A traveller asks for a portable mirror because hotel-room mirrors can be poorly lit, hard to approach, or unavailable while someone uses the bathroom.</p><a href="${sources[2].url}" target="_blank" rel="noopener noreferrer">Read the public discussion <span aria-hidden="true">↗</span></a></article></div><p class="evidence-caption">Independent, self-selected public discussions—not AERLOR reviews, endorsements or a representative survey. Individual preferences vary. We do not infer every contributor’s gender. ${small('The full context','journal/the-getting-ready-gap/')}</p>`;
const calculator=()=>`<section class="investment section-pad" id="investment"><div>${eye('MAKE THE BUSINESS CASE YOURS')}<h2>A room-level investment.<br><em>A stay-level perspective.</em></h2><p>Translate an equipment budget into a cost per occupied room-night. Use your own quote, room count and operating assumptions. No revenue or retention uplift is assumed.</p></div><form id="investment-form" class="calculator-form"><div class="field-row"><label>Equipped rooms<input name="rooms" type="number" min="1" max="100000" step="1" value="100" required></label><label>Equipment cost per room (USD)<input name="cost" type="number" min="0.01" max="100000" step="0.01" value="99" required></label></div><div class="field-row"><label>Planning life (years)<input name="years" type="number" min="1" max="20" step="1" value="3" required></label><label>Average occupancy (%)<input name="occupancy" type="number" min="1" max="100" step="1" value="75" required></label></div><div class="calculator-results" aria-live="polite"><div><span>Equipment budget</span><strong data-investment-total>$9,900</strong></div><div><span>Per occupied room-night</span><strong data-investment-night>$0.12</strong></div></div><p class="fineprint">Illustrative USD budgeting inputs, not AERLOR prices or a product-life promise. Excludes tax, freight, financing, failures, maintenance and disposal. Formula: cost per room ÷ (365 × years × occupancy). Occupancy is a proportion, not a percentage point.</p><p class="form-error" id="investment-error" role="alert"></p></form></section>`;
const docs=[{slug:'hospitality-collection',file:'aerlor-hospitality-collection.pdf',title:'The hospitality collection',category:'Lookbook',pages:8,desc:'The AERLOR point of view, three product families and two room expressions.'},{slug:'hotel-upgrade-guide',file:'aerlor-hotel-upgrade-guide.pdf',title:'The considered-room business case',category:'Hotel guide',pages:6,desc:'Guest perspectives, room-level economics and a persuasive, measurable pilot proposal.'},{slug:'procurement-guide',file:'aerlor-procurement-guide.pdf',title:'Procurement, without the guesswork',category:'Procurement',pages:5,desc:'Compare configurations, define the technical evidence and prepare a decision-ready brief.'},{slug:'pilot-toolkit',file:'aerlor-pilot-toolkit.pdf',title:'The hotel pilot toolkit',category:'Operations',pages:5,desc:'A room audit, evaluation scorecard and rollout checklist for your team.'}];
const docCard=d=>`<article class="resource-card">${eye(d.category)}<h3>${e(d.title)}</h3><p>${e(d.desc)}</p><div>${small('Read the guide','resources/'+d.slug+'/')}<a href="${url('documents/'+d.file)}" download>Download PDF ↓</a></div></article>`;
const resourcesStrip=()=>`<section class="section-pad resources-strip">${eye('FOR THE CONVERSATION THAT COMES NEXT')}<div class="section-heading"><h2>Bring the vision<br><em>to the table.</em></h2><p>Useful, shareable material for owners, operations teams and the people specifying the room.</p></div><div class="resource-grid">${docs.slice(0,3).map(docCard).join('')}</div></section>`;
// Preserve the existing hero and working progressive 3D, then expand its surrounding story.
const template=resolve(root,'templates/home-r2.html');mkdirSync(dirname(template),{recursive:true});if(!existsSync(template))writeFileSync(template,readFileSync(resolve(root,'index.html'),'utf8'));
let home=readFileSync(template,'utf8');
home=home.replace('<body>','<body data-page="home" data-legacy="true">').replace(/<header class="site-header"[\s\S]*?<\/nav>\s*<main id="main">/,header()+'<main id="main">');
home=home.replace('<link rel="stylesheet" href="/src/style.css" />','<link rel="stylesheet" href="/src/style.css" /><link rel="stylesheet" href="/src/storefront.css" />');
home=home.replace('Meet a new perspective on haircare essentials.<br>Thoughtfully imagined for the rooms you create.','Haircare, illuminated mirrors and styling tools.<br>For the moments before your guests step out.');
home=home.replace('AERLOR is exploring a more considered kind of essential — objects that feel as much a part of your property as everything around them.','Make getting ready part of the experience, not the compromise. AERLOR brings haircare, mirrors and styling into one considered room story.');
home=home.replace('<section class="collection section-pad"',categories()+'<section class="collection section-pad"');
home=home.replace('02 — THE FIRST COLLECTION','THE HAIRCARE COLLECTION').replace('Meet the first collection','Discover the room ritual');
home=home.replace('Haircare is our first focus. We are also exploring complementary vanity and wardrobe essentials. No additional products or launch dates are confirmed.','Explore the complete development collection: hairdryers, illuminated makeup mirrors and curling tools, each in Lite and Premium expressions. Product pages explain the design direction, intended placement and the technical details required before release.');
home=home.replace('<section class="closing">',resourcesStrip()+'<section class="closing">');
home=home.replace(/<footer class="footer">[\s\S]*?<\/footer>/,footer());
home=home.replace('This is a prelaunch design preview, not a shop.','The collection is in development; online purchase is not yet open.');
home=home.replace('It does not submit data, use browser storage, or subscribe you to marketing.','It does not submit personal data or subscribe you to marketing. The project bag stores only your selected product references, finishes and quantities on your device.');
home=home.replace('<script type="module" src="/src/main.ts"></script>','<script type="module" src="/src/main.ts"></script><script type="module" src="/src/storefront.ts"></script>');
home=home.replaceAll('AERLOR PRO','AERLOR PREMIUM').replaceAll('>PRO<span','>PREMIUM<span').replaceAll('PRO explores','Premium explores').replaceAll('between PRO and LITE','between Premium and Lite').replace('value="PRO" /> PRO','value="PREMIUM" /> Premium');
home=home.replace('<button class="text-link" data-product="pro">Explore PRO <span aria-hidden="true">↗</span></button>',small('View Hairdryer Premium','products/hairdryer-premium/'));
home=home.replace('<button class="text-link" data-product="lite">Explore LITE <span aria-hidden="true">↗</span></button>',small('View Hairdryer Lite','products/hairdryer-lite/'));
home=home.replace('<button class="button button-light" data-inquiry>Plan a pilot for your property <span aria-hidden="true">↗</span></button>',link('Plan your property','hospitality/wholesale/','button-light')+'<button class="text-link local-planner-link" data-inquiry>Plan a pilot for your property <span aria-hidden="true">↗</span></button>');
home=home.replace('AERLOR is creating considered haircare essentials for exceptional stays. Explore our first hospitality collection and shape a pilot for your property.','AERLOR brings hairdryers, illuminated makeup mirrors and styling tools into one considered hospitality collection. Explore Lite and Premium for your rooms.');
writeFileSync(resolve(root,'index.html'),home);paths.push('index.html');
page('collection','The collection','Hairdryers, illuminated makeup mirrors and curling tools. Discover Lite and Premium expressions for considered hospitality.',hero('THE AERLOR COLLECTION','Every detail.<br><em>One point of view.</em>','Haircare, light and the finishing touch. Build a getting-ready experience that feels like it belongs to your property.','mirror-premium.svg')+`<section class="section-pad catalog-section"><div class="catalog-toolbar"><div class="filter-group" aria-label="Filter by collection"><button data-family-filter="all" aria-pressed="true">All</button><button data-family-filter="hairdryers" aria-pressed="false">Hairdryers</button><button data-family-filter="mirrors" aria-pressed="false">Mirrors</button><button data-family-filter="curlers" aria-pressed="false">Curlers</button></div><label class="tier-filter">Expression<select id="tier-filter"><option value="all">Lite & Premium</option><option>Lite</option><option>Premium</option></select></label></div><p class="filter-count" id="filter-count" role="status">6 collection concepts</p>${grid(products)}${note}${small('Compare every detail','compare/')}</section>`+cta());
for(const [key,f] of Object.entries(familyData)){page('collection/'+key,f.name+' for hotels',f.intro,hero('THE '+f.name.toUpperCase()+' COLLECTION',f.title,f.intro,f.image)+`<section class="section-pad family-intro"><h2>Lite or Premium.<br><em>Your room, your expression.</em></h2><p>${f.body}</p>${grid(products.filter(p=>p.family===key))}${note}</section>`+`<section class="split-story section-pad"><div>${eye('DESIGN THE WHOLE MOMENT')}<h2>${key==='mirrors'?'More than a mirror.<br><em>A place to prepare.</em>':key==='curlers'?'A service, not just<br><em>another appliance.</em>':'It starts with the dryer.<br><em>It belongs to the stay.</em>'}</h2></div><div><p>${key==='mirrors'?'Think about where a guest sits, where the light falls and whether two people can get ready comfortably. A useful mirror makes the room work—not just look complete.':key==='curlers'?'Choose an on-request program when it fits your guests and operations. Confirm the exact-model safety evidence, cooling and cleaning routine before lending any heated tool.':'The right room standard brings aesthetics and everyday use together. Start with the desired guest experience, then validate performance, care and commercial support on the actual model.'}</p>${small('See the hotel perspective','hospitality/')}</div></section>`+cta());}
for(const p of products){const others=products.filter(x=>x.tier===p.tier&&x.id!==p.id).slice(0,2);page('products/'+p.slug,p.name,p.summary,breadcrumb(p.name)+`<section class="product-page" data-product-page="${p.id}"><div class="product-gallery ${p.tier==='Premium'?'premium-art':'lite-art'}"><span class="gallery-label">${e(p.code)} / ${e(p.family.toUpperCase())}</span><img data-gallery-image src="${img(p.image)}" alt="${e(p.name)} ${e(p.finish)} design study" width="800" height="900" fetchpriority="high"><p>Design study · not production photography</p></div><div class="product-buybox">${eye('AERLOR / '+p.tier.toUpperCase())}<h1>${e(p.name.replace(' '+p.tier,''))}<br><em>${p.tier}.</em></h1><p class="product-tagline">${e(p.tagline)}</p><p>${e(p.summary)}</p><div class="price-line"><strong data-price="${p.id}">Pricing by project</strong><span data-availability="${p.id}">Collection development</span></div><div class="buy-options"><label>Finish direction<select data-product-finish>${p.finishes.map(f=>`<option>${e(f)}</option>`).join('')}</select></label><label>Quantity<input data-product-quantity type="number" min="1" max="5000" value="1" step="1" inputmode="numeric"></label></div><button class="button button-dark full-width" data-add="${p.id}">Add to your project ${arrow}</button><a class="text-link" href="${url('pricing/')}">Wholesale and purchase options ${arrow}</a><p class="fineprint">A project selection is not an order. Final price, specification and supply timing are confirmed before purchase.</p><div class="product-utility"><a href="#specifications">Specification brief ↓</a><a href="${url('documents/'+p.document)}" download>Download product PDF ↓</a></div></div></section><section class="product-story section-pad"><div>${eye('THE DESIGN INTENTION')}<h2>${e(p.tagline)}</h2></div><div><p>${e(p.story)}</p><p class="placement"><strong>Imagined for</strong><br>${e(p.placement)}</p></div></section><section class="feature-notes section-pad">${p.highlights.map((h,i)=>`<article><span>0${i+1}</span><h3>${e(h)}</h3></article>`).join('')}</section><section id="specifications" class="spec-section section-pad"><div>${eye('THE DETAILS, WITH CLARITY')}<h2>The specification<br><em>starts here.</em></h2><p>Use this development brief to shape your requirements. “Defined” identifies the collection concept. “Proposed” describes a design direction. Unverified technical fields are not product claims.</p></div><div class="spec-table"><table><caption>${e(p.name)} development specification</caption><thead><tr><th scope="col">Detail</th><th scope="col">Current brief</th><th scope="col">Status</th></tr></thead><tbody>${p.specs.map(([a,b,c])=>`<tr><th scope="row">${e(a)}</th><td>${e(b)}</td><td><span class="spec-status ${c}">${e(c)}</span></td></tr>`).join('')}</tbody></table></div></section><section class="room-fit section-pad">${eye('MAKE IT WORK IN YOUR ROOMS')}<h2>Consider the placement.<br><em>Then the whole program.</em></h2><p>${e(p.roomNote)}</p><div class="three-notes"><article><h3>Before the sample</h3><p>Confirm the destination market, proposed room location and the exact technical evidence you need.</p></article><article><h3>During evaluation</h3><p>Review the actual unit with engineering and housekeeping. Gather guest feedback without substituting it for safety approval.</p></article><article><h3>Before rollout</h3><p>Agree the final model, written quote, kit contents, lead time and service terms.</p></article></div>${small('Download the procurement guide','resources/procurement-guide/')}</section><section class="section-pad complete-ritual"><div class="section-heading"><h2>Complete<br><em>the ritual.</em></h2><p>Keep the expression consistent.<br>Pair ${e(p.tier)} across the room.</p></div>${grid(others)}<button class="button button-dark" data-bundle="${p.tier}">Add the ${p.tier} room concept ${arrow}</button><p class="fineprint">Adds one hairdryer, one mirror and one curler concept. Adjust quantities in your project bag.</p></section>`+cta(),'data-product-id="'+p.id+'"');}
page('compare','Compare Lite and Premium','Compare the six AERLOR collection concepts, intended room placements and specification readiness.',hero('A MORE CONSIDERED CHOICE','The right expression.<br><em>For your rooms.</em>','Compare design direction and intended placement across the collection. Technical performance is not represented as equivalent or superior until tested.',null)+`<section class="section-pad comparison"><div class="table-scroll"><table><caption>Lite and Premium collection planning comparison</caption><thead><tr><th scope="col">Collection</th><th scope="col">Lite</th><th scope="col">Premium</th><th scope="col">Before purchasing</th></tr></thead><tbody>${Object.entries(familyData).map(([key,f])=>{const a=products.find(p=>p.family===key&&p.tier==='Lite'),b=products.find(p=>p.family===key&&p.tier==='Premium');return `<tr><th scope="row">${f.name}</th><td><strong>${a.material}</strong><p>${a.placement}</p>${small('View Lite','products/'+a.slug+'/')}</td><td><strong>${b.material}</strong><p>${b.placement}</p>${small('View Premium','products/'+b.slug+'/')}</td><td>Exact-model specification, market approvals, agreed price and hospitality-use terms.</td></tr>`;}).join('')}</tbody></table></div>${note}</section>`+cta());
page('hospitality','For hotels: make getting ready part of the stay','A considered haircare and vanity experience for hotels. Explore guest perspectives, room planning and a measurable pilot.',hero('AERLOR FOR HOSPITALITY','They booked a room.<br><em>Give them a feeling.</em>','The welcome matters. So does the moment before dinner, the confidence before a meeting, and the ease of getting ready together.','mirror-premium.svg','hotel-hero')+`<section class="section-pad story-opening"><p class="story-lead">You have considered the bed.<br>The scent. The light.<br><em>Don’t let the ritual be the compromise.</em></p><div><p>Guests bring their routines with them—even when they leave their tools at home. A considered hairdryer, a well-positioned mirror and a thoughtful styling service can make the room feel ready for real life.</p><p>That is the opportunity AERLOR is built around: turn a functional corner of the room into another expression of your hospitality.</p></div></section>`+categories()+`<section class="section-pad guest-voices">${eye('LISTEN TO THE MOMENTS BETWEEN THE BOOKINGS')}<h2>The small details<br><em>are not always small.</em></h2><p class="section-intro">Public travel discussions reveal practical frustrations worth listening to. We use them as design questions—not as invented customer success stories.</p>${voices()}</section><section class="hospitality-scenes section-pad">${eye('DESIGNED AROUND THE STAY')}<div class="scene-cards"><article><span>01 / THE CITY STAY</span><h3>Ready before<br><em>the first meeting.</em></h3><p>Imagine a guest getting ready without unpacking an extra appliance or searching for a better-lit mirror. A room that respects their routine respects their time.</p></article><article><span>02 / THE WEEKEND AWAY</span><h3>More room<br><em>for the occasion.</em></h3><p>A dinner reservation. A wedding weekend. A shared dressing space that works for two. Thoughtful amenities can support the moments your property is there to host.</p></article><article><span>03 / THE SUITE EXPERIENCE</span><h3>A detail that<br><em>belongs to the room.</em></h3><p>Coordinate the finish, the presentation and the service. A suite standard should feel intentional from the doorway to the vanity.</p></article></div><p class="fineprint">Illustrative guest scenarios, not reports of AERLOR installations or measured outcomes.</p></section>`+calculator()+`<section class="section-pad pilot-story"><div>${eye('START WITH EVIDENCE, NOT A PROPERTY-WIDE LEAP')}<h2>Make the first rooms<br><em>your best argument.</em></h2><p>Choose a limited pilot after the product and market approvals are ready. Give operations a baseline and guests a voice. Scale what genuinely works.</p></div><ol class="editorial-steps"><li><strong>Define the room standard</strong><p>Room types, guest routines, placement, voltage and the service you want to provide.</p></li><li><strong>Evaluate the actual product</strong><p>Engineering, housekeeping and a defined sample review—not a decision made from a rendering.</p></li><li><strong>Measure the experience</strong><p>Guest feedback, amenity requests, service incidents, cleaning time and staff observations.</p></li><li><strong>Build a funded rollout</strong><p>Confirm the commercial terms, spare pool, delivery phases and responsibilities.</p></li></ol></section>`+resourcesStrip()+cta());
const inquiryForm=(kind='wholesale')=>`<form class="project-form" id="project-form" data-form-kind="${kind}" novalidate><div class="field-row"><label>Your name<input name="name" autocomplete="name" maxlength="100" required></label><label>Work email<input name="email" type="email" autocomplete="email" maxlength="200" required></label></div><label>Hotel, group or studio<input name="company" autocomplete="organization" maxlength="160" required></label><div class="field-row"><label>Country<select name="country" aria-label="Country" autocomplete="country" required><option value="">Choose destination</option><option value="CA">Canada</option><option value="US">United States</option><option value="GB">United Kingdom</option><option value="EU">European Union</option><option value="AE">United Arab Emirates</option><option value="OTHER">Another market</option></select></label><label>Number of rooms<input name="rooms" type="number" min="1" max="100000" step="1" inputmode="numeric" required></label></div><div class="field-row"><label>Your role<select name="role" aria-label="Your role" required><option value="">Choose your role</option><option>Owner / asset manager</option><option>General manager / operations</option><option>Procurement</option><option>Designer / specifier</option><option>Distributor / partner</option><option>Other</option></select></label><label>Project timing<select name="timing" aria-label="Project timing" required><option value="">Choose a time frame</option><option>Exploring options</option><option>Next 3 months</option><option>3–6 months</option><option>6–12 months</option><option>More than 12 months</option></select></label></div><fieldset><legend>Collections of interest</legend><div class="checkbox-row"><label><input type="checkbox" name="collections" value="Hairdryers"> Hairdryers</label><label><input type="checkbox" name="collections" value="Mirrors"> Mirrors</label><label><input type="checkbox" name="collections" value="Curlers"> Curlers</label></div></fieldset><label>Tell us about the experience you want to create<textarea name="message" maxlength="3000" rows="4"></textarea></label><label class="honeypot" aria-hidden="true">Leave this field empty<input name="website" tabindex="-1" autocomplete="off"></label><label class="consent-line"><input type="checkbox" name="consent" required> I agree to share this inquiry with AERLOR to discuss my project. This does not subscribe me to marketing.</label><p class="fineprint">Your project bag is included in the brief. No order or payment is created. <a href="${url('privacy/')}">Read the privacy notice.</a></p><div id="verification-widget"></div><div class="form-error" id="project-error" role="alert" tabindex="-1"></div><div class="form-actions"><button class="button button-dark" type="submit" data-project-submit>Prepare my project brief ${arrow}</button><button class="text-link" type="button" data-save-brief>Save a copy ↓</button></div><p id="project-status" role="status"></p><div id="project-delivery" hidden><a class="button button-dark" id="email-project" href="#">Open email with my brief ${arrow}</a><p class="fineprint">Your email app opens with a draft. Review and send it there. Nothing is sent merely by preparing the brief.</p></div></form>`;
page('hospitality/wholesale','Wholesale and bulk programs','Build a hotel-specific AERLOR proposal: quantities, room types, technical requirements and a phased rollout.',hero('WHOLESALE / BULK / PROJECTS','One room or a portfolio.<br><em>Start with the right brief.</em>','Not a one-size-fits-all price list. A clear proposal built around your room mix, destination, quantities and the service behind the product.',null)+`<section class="section-pad wholesale-story"><div>${eye('BUY THE ROOM STANDARD, NOT JUST THE UNIT')}<h2>A more complete<br><em>procurement conversation.</em></h2></div><div><p>Choosing a guestroom appliance is not only a design decision. It is a question of electrical compatibility, daily handling, replacement needs and who stands behind the exact model you receive.</p><p>Build the brief once. Use it to align your owner, purchasing team, engineering and housekeeping before agreeing the final commercial offer.</p></div></section><section class="section-pad purchase-bands"><article><span>01 / EVALUATE</span><h3>Sample & specification</h3><p>Define the intended configuration and required evidence. Sample availability and terms must be confirmed before payment.</p></article><article><span>02 / VALIDATE</span><h3>Property pilot</h3><p>Use a defined room group, a clear scorecard and a controlled service plan to test fit.</p></article><article><span>03 / STANDARDISE</span><h3>Full-property rollout</h3><p>Plan quantities, spares, destination requirements and phased delivery around the property.</p></article><article><span>04 / SCALE</span><h3>Portfolio program</h3><p>Create a common specification, then account for each location’s electrical and operational needs.</p></article></section><section class="quote-inclusions section-pad">${eye('WHAT A COMPLETE QUOTE SHOULD TELL YOU')}<h2>No important detail<br><em>left to inference.</em></h2><div class="three-notes"><article><h3>The product</h3><p>Exact model and revision, finish, electrical version, accessories, unit quantities and approved specification.</p></article><article><h3>The commercial offer</h3><p>Currency, unit and volume pricing, taxes, freight, duties where relevant, payment schedule and quote validity.</p></article><article><h3>The delivery & support</h3><p>Agreed lead time, delivery destinations, warranty scope, spare parts and the process for service or replacement.</p></article></div>${band('Current purchasing status','The collection is in development. This page prepares a genuine procurement conversation; it does not promise stock, approved pricing, supplier certification or a shipment date.')}</section><section class="quote-section section-pad" id="project-brief"><div>${eye('YOUR PROPERTY, IN FOCUS')}<h2>Let’s make it<br><em>feel like you.</em></h2><p>Share the room count, destination and experience you are planning. A useful proposal begins with your property—not a generic sales pitch.</p>${small('Choose your collection first','collection/')}<div class="quote-aside"><strong>Prefer a document?</strong><p>Use the procurement guide to align your internal team.</p><a href="${url('documents/aerlor-procurement-guide.pdf')}" download>Download procurement PDF ↓</a></div></div>${inquiryForm()}</section>`+resourcesStrip());
page('hospitality/groups','For hotel groups and operators','Develop a coherent guestroom amenity standard across room tiers, brands and destinations.',hero('FOR OWNERS / OPERATORS / GROUPS','One philosophy.<br><em>Room for every property.</em>','Bring consistency to the guest ritual without making every room feel the same. Plan Lite and Premium across your room categories and portfolio.','dryer-champagne.svg')+`<section class="section-pad split-story"><div><h2>Standardise the intention.<br><em>Specify the differences.</em></h2></div><div><p>A portfolio program begins with a common product and service brief. Room category, guest mix and destination requirements then shape the final configuration.</p><p>Use Lite for a considered everyday expression, Premium for a signature presentation, and a controlled lending pool where a styling amenity makes more sense on request.</p></div></section><section class="section-pad"><div class="three-notes"><article><h3>A clear portfolio matrix</h3><p>Map properties, room categories, required voltage and plug, quantities and replacement reserves.</p></article><article><h3>A single technical record</h3><p>Keep the exact model, approvals, approved sample and written terms attached to the purchasing decision.</p></article><article><h3>A phased rollout</h3><p>Begin with qualified pilot properties. Expand after operational acceptance and funded purchasing approval.</p></article></div></section>`+calculator()+cta('A room standard<br><em>your team can stand behind.</em>','Start with a property matrix and a common evaluation brief.'));
page('hospitality/designers','For designers and specifiers','Coordinate the haircare and vanity ritual with your guestroom design and technical requirements.',hero('FOR DESIGNERS / ARCHITECTS / SPECIFIERS','The last detail.<br><em>Part of the first impression.</em>','A product on the vanity should belong to the room as naturally as the stone, the light and the fittings around it.','mirror-premium.svg')+`<section class="section-pad split-story"><div><h2>A coherent material story.<br><em>A practical room plan.</em></h2></div><div><p>Explore soft-matte and metal-finish directions across a complete getting-ready collection. Then test how the actual product sits in the room: reach, light, outlets, cable routing and cleaning clearance.</p><p>Concept artwork is a conversation starter, not a fabrication drawing. Final dimensions, materials and installation requirements must come from the approved model.</p></div></section><section class="section-pad"><div class="three-notes"><article><h3>Coordinate</h3><p>Choose a finish direction, a room category and the visual relationship between the appliances and the interior.</p></article><article><h3>Validate</h3><p>Review an actual sample alongside the room mock-up. Include engineering and housekeeping in the decision.</p></article><article><h3>Document</h3><p>Specify the approved model and revision. Keep technical approvals, care requirements and commercial terms together.</p></article></div>${band('Technical asset policy','We will not present concept dimensions or generated CAD as approved production drawings. Use the product specification briefs to record what must be confirmed.')}</section>`+resourcesStrip()+cta());
page('pricing','Pricing and purchasing','A transparent path from collection selection to a complete hotel quote and approved checkout.',hero('PRICING / PURCHASING','A considered investment.<br><em>A clear conversation.</em>','Choose the room experience first. Confirm the complete commercial offer before committing to an order.',null)+`<section class="section-pad pricing-intro"><h2>Price the project.<br><em>Not an imaginary discount.</em></h2><p>We do not publish a made-up retail anchor or imply savings from a price no one has paid. Current collection pricing is quote-led while exact products, approvals and supply arrangements are finalised.</p><div class="pricing-paths"><article>${eye('INDIVIDUAL PURCHASE')}<h3>Buy for yourself.</h3><p>Online purchasing opens when a released product has an approved price, market configuration and supply commitment. Your bag will show eligible items and the final checkout path.</p>${small('Explore the collection','collection/')}</article><article>${eye('HOTEL / WHOLESALE')}<h3>Equip your rooms.</h3><p>Build a product list and room count. A written quote should make unit pricing, taxes, freight, lead time and hospitality-use terms explicit.</p>${small('Build a wholesale brief','hospitality/wholesale/')}</article><article>${eye('PORTFOLIO / CORPORATE')}<h3>Create a standard.</h3><p>Coordinate room tiers, destinations and delivery phases under one specification process. A network relationship is not a promise of universal product approval.</p>${small('Plan a group program','hospitality/groups/')}</article></div></section><section class="section-pad price-process"><div>${eye('FROM YOUR SELECTION TO YOUR ORDER')}<h2>Every step.<br><em>No surprises.</em></h2></div><ol class="editorial-steps"><li><strong>Select products and quantities</strong><p>Use your project bag to compare the collection and build a room set.</p></li><li><strong>Confirm destination and requirements</strong><p>Electrical version, intended placement, kit contents and timing affect the final proposal.</p></li><li><strong>Review a written price</strong><p>Currency, unit prices, volume basis, tax, shipping and applicable terms must be stated.</p></li><li><strong>Use secure checkout when eligible</strong><p>Only released, priced configurations can proceed to payment. Card details are entered on the payment provider’s checkout, not in an AERLOR form.</p></li></ol></section>`+calculator()+cta());
page('resources','The hospitality resource library','Download the AERLOR lookbook, hotel upgrade guide, procurement checklist, pilot toolkit and product specification briefs.',hero('THE RESOURCE LIBRARY','Bring the vision<br><em>to the table.</em>','A useful story for the owner. A clear brief for purchasing. A practical checklist for the people who make the room work.',null)+`<section class="section-pad"><div class="resource-grid">${docs.map(docCard).join('')}</div><div class="section-heading resource-heading"><h2>Product<br><em>specification briefs.</em></h2><p>Six development briefs. Each separates design intention from technical details that still require verification.</p></div><div class="spec-downloads">${products.map(p=>`<article><span>${e(p.code)}</span><h3>${e(p.name)}</h3><a href="${url('documents/'+p.document)}" download aria-label="Download ${e(p.name)} specification brief">PDF ↓</a></article>`).join('')}</div><p class="fineprint">Documents are versioned development and planning materials. They are not certificates, final production specifications or binding commercial offers.</p></section>`+cta());
for(const d of docs)page('resources/'+d.slug,d.title,d.desc,breadcrumb(d.title,'Resources','resources/')+`<section class="document-intro section-pad">${eye(d.category+' / PDF')}<h1>${e(d.title)}</h1><p class="lead">${e(d.desc)}</p><div class="document-actions"><a class="button button-dark" href="${url('documents/'+d.file)}" download>Download the PDF ↓</a><a class="text-link" href="${url('documents/'+d.file)}" target="_blank" rel="noopener">Open in a new tab ${arrow}</a></div></section><section class="document-viewer section-pad"><iframe src="${url('documents/'+d.file)}#view=FitH" title="${e(d.title)} PDF preview" loading="lazy"></iframe><p class="fineprint">PDF preview unavailable on your device? Use the download or new-tab link above. This is a development guide, not an approved specification or commercial quote.</p></section>`);
page('journal/the-getting-ready-gap','The getting-ready gap','What public travel conversations reveal about hotel hairdryers, styling tools and makeup mirrors.',hero('THE AERLOR JOURNAL / GUEST PERSPECTIVES','A beautiful room.<br><em>A familiar compromise?</em>','Listen to what happens between the check-in and the evening out. The getting-ready ritual deserves a place in the hospitality conversation.',null)+`<article class="editorial-article section-pad"><p class="article-deck">Packing less should not mean feeling less like yourself.</p><p>In women-focused travel communities and beauty discussions, people talk about the practical trade-offs behind a small suitcase: the styling tool that takes too much space, the dryer they do not know they can rely on, and the mirror that is nowhere near useful light.</p><p>Those conversations are not a market-wide survey. They are useful reminders that the room is experienced through routines as well as photographs.</p>${voices()}<h2>Listen without assuming<br><em>everyone wants the same thing.</em></h2><p>Some travellers happily use the hotel dryer. Others simplify their hair routine, bring a familiar tool or value a specific attachment. Hair texture, styling habits, mobility, eyesight and the purpose of a trip all change what “thoughtful” means.</p><p>Our response is not to promise one appliance will suit everyone. It is to ask better room-planning questions: where can a guest get ready comfortably, what is included, what can be borrowed, and how clearly is that communicated?</p><h2>The category already<br><em>has a hospitality precedent.</em></h2><p>In a 2016 announcement, Hyatt Centric described introducing Drybar dryers into guestrooms. Four Seasons Resort Oahu lists a lighted makeup and shaving mirror among its amenities. Hyatt also describes a service through which guests can buy or borrow everyday essentials.</p><p>These are examples from other operators, not AERLOR customers or partners. They establish that the getting-ready experience can be part of an amenity strategy; they do not establish an AERLOR revenue, satisfaction or loyalty result.</p><h2>Turn the insight<br><em>into a better pilot.</em></h2><p>Ask guests what they use and what they miss. Review the actual sample, placement and instructions. Track feedback alongside service calls, housekeeping time and operational issues. Let the evidence from your property decide the next step.</p><section class="source-notes"><h3>Sources & context</h3>${sources.map((s,i)=>`<article><span>${i+1}</span><div><a href="${s.url}" target="_blank" rel="noopener noreferrer">${e(s.title)} — ${e(s.publisher)} ${arrow}</a><p>${e(s.note)}</p></div></article>`).join('')}<p class="fineprint">Reviewed 4 November 2026. Public anecdotes are self-selected and unverified as hotel bookings. Quotation is attributed to the discussion, not used as a product endorsement. No affiliation with the named operators or brands is implied.</p></section></article>`+cta());
page('about','The AERLOR perspective','Considered essentials for the moments that make a hotel stay feel personal.',hero('THE AERLOR PERSPECTIVE','Hospitality is personal.<br><em>The essentials should be too.</em>','We are building a collection around the moments guests bring with them: a morning routine, a final check in the mirror, the preparations for a night worth remembering.','mirror-premium.svg')+`<section class="section-pad split-story"><h2>Not more things.<br><em>More consideration.</em></h2><div><p>A room can be beautifully designed and still ask a guest to improvise. AERLOR begins with the belief that everyday haircare and vanity tools deserve the same attention as the rest of the stay.</p><p>Our collection brings hairdryers, illuminated mirrors and styling tools into one design language, with Lite and Premium expressions for different rooms and service models.</p></div></section><section class="section-pad"><div class="three-notes"><article><h3>The guest, first</h3><p>Design around real routines, different preferences and the way a room is actually used.</p></article><article><h3>The property, too</h3><p>Consider the purchasing decision, engineering requirements, daily care and the service behind the object.</p></article><article><h3>Evidence over embellishment</h3><p>Separate the design ambition from verified product performance. A compelling story should never require invented proof.</p></article></div>${band('Where we are today','AERLOR is a collection in development. The current visuals are original design studies. We are not claiming existing hotel installations, certified production models or ready-to-ship stock.')}</section>`+cta());
page('contact','Contact AERLOR','Discuss your hotel, project, product questions or distribution requirements with AERLOR.',hero('A CONVERSATION WORTH HAVING','Tell us about<br><em>your kind of stay.</em>','A boutique hideaway, a city hotel, a suite collection or a portfolio. Start with the experience you want guests to have.',null)+`<section class="quote-section section-pad"><div>${eye('THE AERLOR TEAM')}<h2>Thoughtful questions.<br><em>A useful next step.</em></h2><p>Share your property brief, request a specification discussion or tell us what would make the collection useful to your team.</p><div class="contact-direct"><span>Business inquiries</span><a data-contact-email hidden></a><p data-contact-loading>Use the project form to prepare a brief. Email delivery options appear when the contact service is available.</p></div><p class="fineprint">No automatic mailing-list subscription. No order or sample reservation is created by an inquiry.</p>${small('Read the hotel guide','resources/hotel-upgrade-guide/')}</div>${inquiryForm('contact')}</section>`);
page('support','AERLOR support','Find collection information, purchasing guidance, technical-document requirements and the right contact route.',hero('SUPPORT / INFORMATION','Clear answers.<br><em>A considered response.</em>','Find your next step, whether you are specifying a room, reviewing a proposal or asking about an order.',null)+`<section class="section-pad support-grid"><article><h2>Product information</h2><p>Product pages and specification briefs explain the current collection direction and the fields that require verification before release.</p>${small('Browse product briefs','resources/')}</article><article><h2>Quotes & purchasing</h2><p>For a useful quote, include the product selection, quantity, destination, room mix and required delivery window.</p>${small('Prepare a project brief','hospitality/wholesale/')}</article><article><h2>Order & service questions</h2><p>Include your order or quote reference in a message to the team. Do not email card numbers, passwords or sensitive payment information.</p>${small('Contact AERLOR','contact/')}</article><article><h2>Delivery, returns & warranty</h2><p>The written offer for a released product must state the applicable delivery and support terms before you purchase.</p>${small('How terms are confirmed','shipping-returns/')}</article></section><section class="section-pad support-faq"><h2>Before <em>you begin.</em></h2>${[['Can I place a paid order now?','Online purchasing is not yet open. Checkout is enabled only for released products with approved pricing, market configuration, merchant setup and supply terms.'],['Can I specify a product from a rendering?','Use the design study to discuss aesthetics, not as a production drawing. Confirm dimensions, electrical suitability and required safety evidence on the actual approved model.'],['Can curlers go into every room?','Do not deploy a heated styling tool without the exact-model approval, written instructions and an operational safety review. A managed lending program may be a better starting point.'],['Will my inquiry subscribe me to marketing?','No. A project inquiry is for the conversation you request. It does not enrol you in promotional emails.']].map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</section>`);
const legalPage=(path,title,desc,sections)=>page(path,title,desc,`<section class="legal-page section-pad">${eye('AERLOR / '+title.toUpperCase())}<h1>${title}</h1><p class="legal-date">Website information · updated 4 November 2026</p>${sections.map(([h,b])=>`<section><h2>${h}</h2>${b}</section>`).join('')}</section>`);
legalPage('shipping-returns','Delivery, returns & warranty','How delivery, returns and hospitality-use support are defined before an AERLOR order.',[['Before purchasing','<p>The collection is in development and no current stock or delivery date is promised. A released product must have a written commercial offer before payment is accepted.</p>'],['Delivery','<p>Your offer should state the shipment destination, currency, dispatch or delivery window, freight charges, taxes and duties where relevant, and the responsibility for delivery arrangements. A website design study is not a shipment commitment.</p>'],['Returns and cancellations','<p>Applicable return and cancellation terms must be presented before purchase. Bespoke, wholesale and retail orders may have different terms. Do not assume a consumer-style return period applies to a negotiated corporate order, or that any mandatory legal right is excluded.</p>'],['Hospitality-use warranty','<p>Confirm that the exact product and intended hotel use are covered in writing. The approved offer should identify the warranty provider, term, coverage, exclusions and the process for reporting a fault.</p>'],['Questions or an existing reference',`<p>Use the contact page and include your quote or order reference. Never include a card number or payment password.</p>${small('Contact the team','contact/')}`]]);
legalPage('privacy','Privacy','How this AERLOR website handles project selections, inquiries and checkout.',[['The current experience','<p>This site presents a collection in development. Browsing does not create an account or subscribe you to marketing. No advertising pixels or behavioural analytics are installed.</p>'],['Your project bag','<p>The project bag uses local storage on your device for product identifiers, finishes and quantities only. It does not store your name, email, payment details or inquiry text. You can clear the bag at any time. Blocking storage does not prevent browsing; the bag then lasts only for the current page session.</p>'],['Project inquiries','<p>Personal details entered into a project form stay in the page until you choose a delivery action. When the form offers an email draft, you review and send it in your own email application. Preparing a draft or downloading a brief does not transmit it. If direct submission is enabled, the form states that it will send the inquiry and returns a delivery reference only after the configured service accepts it.</p>'],['Checkout','<p>Online payment is disabled until the commercial launch requirements are met. When enabled, card and billing information is entered on Stripe’s hosted checkout. AERLOR does not ask you to type card numbers into this site. The order-status service returns a limited payment status, not an exposed customer record.</p>'],['Technical services','<p>Hosting providers process technical requests to serve the website. Google Fonts receives requests to display the typefaces. When enabled, a verification service may check form abuse; the site discloses that before submission. Essential transaction and request records are handled only through configured server-side services.</p>'],['Contact and changes',`<p>Use the business contact shown on the contact page for privacy questions. Before accepting commercial orders, the responsible seller, operational retention policy and applicable terms must be published and approved.</p>${small('Contact AERLOR','contact/')}`]]);
legalPage('terms','Website & purchasing terms','The distinction between collection development, project planning and an accepted commercial order.',[['Collection information','<p>AERLOR product visuals are original design studies. Proposed finishes, placements and feature directions are not approved technical specifications. No certification, measured performance, available inventory or existing hotel installation is implied.</p>'],['Project selections and quotes','<p>A bag, calculator result or downloaded brief is not an order, reservation or binding quote. Calculator inputs are user-editable planning assumptions, not a representation of product price, life or commercial return.</p>'],['When an order can be accepted','<p>Purchasing can open only after the responsible seller and payment account are established, the exact product is released for the intended market, and price, tax, delivery, warranty and cancellation terms are available to review. A payment redirect or unverified success page is not a fulfillment instruction.</p>'],['Third-party references','<p>Independent travel discussions and operator examples are attributed as context. They are not AERLOR testimonials or endorsements. Named brands retain their own marks and are not represented as partners.</p>'],['Material use and questions',`<p>Collection documents may be shared within your property’s evaluation process. Do not present development material as approved product or compliance documentation. These website notes do not replace the final terms of a negotiated commercial offer or any mandatory rights under applicable law.</p>${small('Ask the team','contact/')}`]]);
legalPage('accessibility','Accessibility','Our approach to an accessible AERLOR browsing and planning experience.',[['Designed for access','<p>The website uses semantic navigation, keyboard-operable controls, visible focus, labelled forms, readable contrast and reduced-motion support. Product information and PDF downloads remain available without the 3D enhancement.</p>'],['Documents','<p>HTML pages provide the core collection and procurement information. PDF documents are supplementary; contact the team for a different format or help accessing specific information.</p>'],['Testing and feedback',`<p>Automated checks and browser reviews are part of release validation. They do not constitute a claim of complete accessibility conformance. Please report any barrier, including the page and the assistive technology or device involved.</p>${small('Report an accessibility issue','contact/')}`]]);
page('cart','Your project bag','Build and review an AERLOR product selection for your property or an eligible purchase.',hero('YOUR PROJECT BAG','A room standard,<br><em>taking shape.</em>','Choose the concepts, finishes and quantities. Then turn your selection into a project brief or review purchasing eligibility.',null)+`<section class="section-pad cart-layout"><div><div id="cart-items"></div><div id="cart-empty"><h2>A little room<br><em>for possibility.</em></h2><p>Add a hairdryer, mirror or styling concept to start your selection.</p>${link('Explore the collection','collection/')}</div><button class="text-link" id="clear-cart" hidden>Clear project bag</button></div><aside class="cart-summary" id="cart-summary"><h2>Your selection</h2><dl><div><dt>Units selected</dt><dd id="cart-units">0</dd></div><div><dt>Product subtotal</dt><dd id="cart-subtotal">Price on request</dd></div><div><dt>Shipping & tax</dt><dd>Confirmed before payment</dd></div></dl><p id="cart-price-note">Unreleased or unpriced items are included in your project brief, not charged.</p>${link('Request project pricing','hospitality/wholesale/#project-brief')}${link('Review purchase','checkout/','button-outline')}<button class="text-link" data-download-cart>Download selection ↓</button><p class="fineprint">Only product selections are saved on your device. No personal details or payment information are stored in the bag.</p></aside></section>`);
page('checkout','Review your purchase','Review your AERLOR selection and proceed to secure payment only for released, priced products.',hero('REVIEW / SECURE CHECKOUT','The details, agreed.<br><em>The next step, clear.</em>','Review the complete selection before leaving for the payment provider. Unreleased products cannot be charged.',null)+`<section class="section-pad checkout-layout"><div><ol class="checkout-progress" aria-label="Checkout steps"><li class="active">1. Review</li><li>2. Secure payment</li><li>3. Confirmation</li></ol><div id="checkout-lines"></div><div class="checkout-notice" id="checkout-readiness" role="status">Checking purchasing availability…</div><label class="consent-line"><input id="checkout-consent" type="checkbox"> I have reviewed the product information and the applicable <a href="${url('terms/')}">purchasing terms</a>.</label><div id="checkout-verification"></div><button class="button button-dark" id="checkout-button" disabled>Continue to secure payment ${arrow}</button><p class="form-error" id="checkout-error" role="alert"></p><p class="fineprint">Card information is collected by Stripe, not by this website. No charge is made by reviewing your bag.</p></div><aside class="checkout-aside"><h2>A property project?</h2><p>Wholesale, multiple destinations and development concepts belong in a written proposal before checkout.</p>${link('Prepare a wholesale brief','hospitality/wholesale/','button-outline')}${small('Return to your bag','cart/')}</aside></section>`);
page('order','Order status','Verify the payment status of an AERLOR checkout session.',hero('YOUR ORDER','A clear confirmation.<br><em>Not an assumption.</em>','Payment status is verified with the provider. A return to this page alone does not mean an order has been paid or shipped.',null)+`<section class="section-pad order-status"><div id="order-result" role="status">Checking your checkout reference…</div>${small('Contact the team','contact/')}${small('Return to your selection','cart/')}</section>`);
writeFileSync(resolve(root,'storefront-pages.json'),JSON.stringify({revision:'hospitality-commerce-r3',base,pages:paths,documents:docs},null,2));
console.log(`Generated ${paths.length} storefront pages for ${base}; ${products.length} product concepts, no invented commercial prices.`);
